$ cat /etc/nginx/sites-available/sklep
upstream sklep_app {
    server 127.0.0.1:8080;
    keepalive 16;
}
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name sklep.lab.local sklep.firma.example;
    client_max_body_size 20m;

    location ^~ /assets/ { alias /var/www/sklep/; expires 7d; access_log off; }
    location = /actuator/health { proxy_pass http://sklep_app; }
    location ^~ /actuator/ { return 404; }
    location /ws/ {
        proxy_pass http://sklep_app;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 1h;
    }
    location / {
        proxy_pass http://sklep_app;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 5s;
        proxy_read_timeout 60s;
    }
    error_page 502 503 504 /przerwa.html;
    location = /przerwa.html { root /var/www/sklep-bledy; internal; }
}
